'use strict';
// Frostbite Pass: 100 authored rescues in 10 connected chapters, building to the voice of the White Beacon.
// Same fields as story-desert.js.
(globalThis.RescueStories=globalThis.RescueStories||[])[1]={chapters:[
{title:'The Ski School',arc:'The North Lodge ski school was mid-lesson when the storm closed the pass. Its students sheltered in warming huts across the slope.',levels:[
{n:'Saoirse',r:'ski instructor',t:'The warming hut',s:'Saoirse, a trainee instructor, led two beginners into a warming hut when the whiteout hit and kept them laughing for three hours.',k:'heard the nine o’clock voice on the hut radio',l:'I told them it was an adventure. It was. I’m very glad it’s over.',x:'At nine, a calm voice came on the hut radio: “Lodge road closes at ten. Stay where you are warm.” Then it hummed.',j:'A voice on the radio, every night at nine.',m:'Mom used to read the forecast at nine.',h:'cold'},
{n:'Teodor',r:'student',t:'First lesson',s:'Teodor, 9, on his first day of skiing, is waiting at the lift shack after a branch heavy with ice brought down the lift’s power cable.',k:'remembers the voice’s strange sign-off',l:'I learned to ski and to wait in one day. Waiting was harder.',x:'The radio voice always ends: “Keep the room warm for whoever comes home.”',j:'Keep the room warm…',m:'That’s what the shelter sign says. Over the door.',h:'cable'},
{n:'Ingrid',r:'ski patroller',t:'The gully',s:'Ingrid, a ski patroller, closed the north gully when snow loaded it overnight and is waiting below it with four skiers she turned back.',k:'knows who warned patrol about the gully',l:'Four people are angry they couldn’t ski the gully. Four people are alive to be angry.',x:'The radio voice warned patrol about that exact gully an hour before it slid.',j:'The voice knows the mountain.',m:'Better than the rangers.',h:'avalanche'},
{n:'Benji',r:'student',t:'The lodge message',s:'Benji, 12, got a message saying his dad would meet him at the empty parking lot. He stayed in the lodge and asked the front desk to check.',k:'heard who answered the fake message',l:'Dad never calls me “buddy.” So I knew.',x:'Someone cut into the lodge channel to correct the fake message. Same calm voice as the forecast.',j:'The voice protects people.',m:'Then why hide?',h:'radio'},
{n:'Margit',r:'lodge manager',t:'The master key',s:'Margit refused to give the lodge’s master key code to a caller claiming to be the insurer. She locked the guest wing and waited by the fire.',k:'found an old keeper’s key in the lodge safe',l:'Two hundred guests sleep in this lodge. Their doors stay shut to strangers.',x:'In the safe: an old brass key tagged “White Beacon — keeper.” Someone borrowed and returned it this week.',j:'Someone’s using the beacon.',m:'The beacon’s been dark for eight years.',h:'code'},
{n:'Oskar',r:'medic',t:'The sealed kit',s:'Oskar, the lodge medic, sealed a frostbite kit for the warming huts on the upper slope. It needs to reach the mountain shelter.',k:'treated someone who came down from the beacon',l:'Thirty frostbite cases this winter. Zero lost fingers. Let’s keep it that way.',x:'Last week an old woman came down from the beacon with frozen hands and a radio headset. She left before I finished.',j:'An old woman. On the beacon.',m:'Alone? In this?',h:'medicine',sup:1},
{n:'Freja',r:'student',t:'The pond rope',s:'Freja, 10, saw her ski pole slide onto the iced pond and stayed behind the rope line, shouting for an instructor.',k:'saw footprints leading up the mountain',l:'The pole is still out there. I’m still here. That’s the right way round.',x:'There were bootprints by the pond going uphill. Small ones. Slow ones.',j:'Uphill. Toward the beacon.',m:'Someone old is climbing alone.',h:'ice'},
{n:'Lars',r:'ski lift operator',t:'The broken lift',s:'Lars could have walked the frozen lift track down. He chose to wait in his booth instead, where patrol knew to find him.',k:'saw a light on the mountain',l:'I run a lift. I know what’s safe to ride and what isn’t.',x:'From the top station I saw a lantern swinging at the White Beacon. First light up there in eight years.',j:'The beacon’s lit again.',m:'Someone lit it.',h:'crossing'},
{n:'Elina',r:'cross-country skier',t:'The red flag',s:'Elina got lost in the storm and found the lodge’s red trail flag, the one landmark she was told to wait by.',k:'heard the voice say her name',l:'The voice on the radio said, “Elina, stay at the red flag.” And I did.',x:'The voice knew my name. It knew everyone’s name on the slope.',j:'Someone’s watching over the whole pass.',m:'From up there.',h:'landmark'},
{n:'Henrik',r:'ski school director',t:'Head count',s:'Henrik runs the North Lodge ski school. He’s the last one on the slope, checking every warming hut against the class lists.',k:'kept a recording of the nine o’clock voice',l:'Every student, every hut, every name. Now the director goes home.',j:'Last one at North Lodge.',m:'And the recording.',h:'verify'}]},
{title:'The Derby',arc:'The Frozen Lake ice-fishing derby was the biggest day of the year. Then the ice began to groan.',levels:[
{n:'Gunnar',r:'derby organizer',t:'Off the ice',s:'Gunnar, the derby organizer, cleared two hundred people off the lake when he heard the ice crack. He’s waiting on shore in the wind.',k:'got a warning from the radio voice',l:'Twenty years of derbies. First year I cancelled. Best decision I ever made.',x:'The voice called the derby line at dawn: “The east ice is thin. Bring them in.”',j:'The voice saved two hundred people.',m:'And never asked for thanks.',h:'ice'},
{n:'Annika',r:'student',t:'The trophy fish',s:'Annika, 13, caught the biggest fish of the derby and left her prize on the ice to walk to shore with her little cousin.',k:'saw someone watching from the ridge',l:'It was a really big fish. My cousin is bigger. And louder.',x:'Someone in an old shelter-keeper’s red coat watched from the ridge with binoculars.',j:'Red coat. The old keepers wore red coats.',m:'Mom had one. It’s in the shelter closet.',h:'cold'},
{n:'Pavlo',r:'bait seller',t:'The bait shack',s:'Pavlo sells bait on the shore. The storm dropped a power line across the only path from his shack.',k:'sold supplies to someone from the beacon',l:'Thirty winters selling bait. First time I was the one on the hook.',x:'Every week an old woman buys candles, matches and tea from me. Always pays exact, always says “for the beacon.”',j:'Candles for the beacon.',m:'She’s been living up there.',h:'cable'},
{n:'Liisa',r:'news reporter',t:'The live shot',s:'Liisa, a reporter, got a message telling the press to gather on the east ice for an announcement. She checked the derby channel and stayed on shore.',k:'knows who sent the false message',l:'I wanted the story. I didn’t want to be the story.',x:'The message came from the developer who wants to turn the shelter into a hotel.',j:'They want the shelter.',m:'They’ll have to get through us.',h:'radio'},
{n:'Rune',r:'derby judge',t:'The scales',s:'Rune, the derby judge, refused to give his scoring login to someone claiming to be the sponsor. He kept the results on paper and walked off the ice.',k:'saw an old keeper’s log',l:'Fair is fair. Nobody touches my results.',x:'The developer’s people asked me if I’d seen the old keeper’s logbook. They want it badly.',j:'What’s in the logbook?',m:'Proof of who owns the shelter, maybe.',h:'code'},
{n:'Birgit',r:'nurse',t:'Warm blankets',s:'Birgit, a nurse, sealed the derby’s first-aid kit for the families on shore and has to send it to the mountain shelter.',k:'heard the voice give first-aid advice',l:'Cold is patient. So are nurses.',x:'The radio voice told shore families exactly how to warm a chilled child. Calm. Like a nurse.',j:'Mom was a nurse.',m:'Mom was the shelter’s nurse.',h:'medicine',sup:1},
{n:'Kalle',r:'student',t:'The fishing hole',s:'Kalle, 8, dropped his rod through the fence at the open water channel and stayed behind the fence instead of reaching.',k:'got a candy from the woman in the red coat',l:'The rod can swim. I can’t. Not in there.',x:'The red-coat lady gave me a peppermint and said, “Good choice, little fisherman.”',j:'Peppermints. Mom always had peppermints.',m:'Every keeper did. It was a shelter thing.',h:'gate'},
{n:'Astrid',r:'snowmobile guide',t:'The thin bridge',s:'Astrid could have driven her snowmobile over the cracked ice bridge. She parked and waited for the tow crew instead.',k:'followed the red coat’s tracks',l:'I know this lake. Tonight, the lake said no.',x:'The red coat’s tracks went around the lake the long way, every single time. Never over the ice.',j:'She knows the rules.',m:'She wrote the rules.',h:'crossing'},
{n:'Mikko',r:'retired fisherman',t:'The lighthouse buoy',s:'Mikko, 82, is waiting by the old lighthouse buoy on the shore, the meeting spot he gave his grandson before his phone died.',k:'knew the shelter’s first keeper',l:'Sixty years on this lake. It still surprises me.',x:'The voice sounds like Katya. Katya ran the shelter when I was young. She’d be ninety now.',j:'Katya. The first keeper.',m:'She trained Mom.',h:'landmark'},
{n:'Sigrid',r:'derby founder',t:'The last line',s:'Sigrid founded the derby fifty years ago. She refused to leave the shore until every hut on the lake was empty.',k:'knows what the voice warned about the ice',l:'Fifty derbies. The best one is the one where everyone goes home.',j:'Last one at Frozen Lake.',m:'And the warning.',h:'verify'}]},
{title:'The Telegraph Club',arc:'The old Signal Cabin is home to the Telegraph Club, retirees who keep the pass’s emergency radio net alive. Tonight they’re stuck on the hill.',levels:[
{n:'Ulla',r:'radio volunteer',t:'Morse at midnight',s:'Ulla, 77, tapped out Morse updates all night until the cabin’s stove pipe started smoking. She’s waiting outside, upwind.',k:'decoded a message from the beacon',l:'Seventy-seven, and still the fastest key on the mountain.',x:'Someone at the beacon taps Morse every night: “K. Still here.”',j:'K. Still here.',m:'K for Katya.',h:'smoke'},
{n:'Dmitri',r:'antenna rigger',t:'Iced wire',s:'Dmitri, the club’s antenna rigger, is stranded below a fallen aerial wire coated in ice.',k:'traced the beacon’s radio channel',l:'I’ve strung wire on this hill for forty years. It finally strung me.',x:'The beacon broadcasts on channel nine. Only the old shelter keepers ever used nine.',j:'Channel nine.',m:'Mom’s channel.',h:'cable'},
{n:'Aino',r:'logkeeper',t:'The meltwater',s:'Aino keeps the club’s logbooks. Meltwater flooded the cabin path, and she’s waiting on the dry porch with the books in a bag.',k:'found a signature in the cabin log',l:'Sixty years of logs. Not one of them gets wet tonight.',x:'Every beacon broadcast is logged and signed “K.” The same K is carved on the shelter door.',j:'The shelter door. We sanded that door last month.',m:'We sanded around the K. We kept it.',h:'water'},
{n:'Branko',r:'radio volunteer',t:'Impostor on the net',s:'Branko heard a voice on the emergency net using a dead member’s call sign. He refused to pass its orders on and waited for Jun.',k:'knows what the impostor wanted',l:'I knew that call sign’s owner for fifty years. That wasn’t him.',x:'The impostor asked where the beacon keeper sleeps. Nobody told.',j:'They’re hunting her too.',m:'Then we protect her.',h:'radio'},
{n:'Hedda',r:'treasurer',t:'The club’s savings',s:'Hedda, the club treasurer, refused to give the club’s bank PIN to a man promising “storm relief money.” She walked out with the cashbox.',k:'knows who paid the beacon’s repairs',l:'Fifty years of bake sales in this box. Nobody’s taking it.',x:'Someone paid to repair the beacon’s generator in cash. The receipt says “for the shelter, for the kids who come back.”',j:'The kids who come back. Mom. And now you.',m:'She knew we’d come.',h:'code'},
{n:'Felix',r:'medic',t:'The heart pills',s:'Felix, a retired doctor, sealed the club members’ heart medications into one box before the evacuation. It needs to reach the shelter.',k:'checked the beacon keeper’s health',l:'Eight old hearts in this club. I intend to keep them all ticking.',x:'I check on her once a month. Ninety, stubborn, and her heart is better than mine.',j:'She’s ninety.',m:'And still keeping the light on.',h:'medicine',sup:1},
{n:'Lotta',r:'student',t:'The cistern fence',s:'Lotta, 11, came to learn Morse and saw the cabin’s cistern overflowing. She stayed outside its fence and called her grandmother.',k:'learned a Morse message from the beacon',l:'Grandma says the fence is there for a reason. Grandma’s always right.',x:'Grandma taught me the beacon’s message: dot dot dash dot… it spells “welcome home.”',j:'Welcome home.',m:'She’s been sending it for eight years.',h:'gate'},
{n:'Viggo',r:'snowshoe guide',t:'The slope',s:'Viggo turned his snowshoe group around when the slope above the cabin cracked, and is waiting in the trees.',k:'saw the keeper on the trail',l:'Mountains don’t care how strong you are. They care how patient you are.',x:'I saw her on the trail with a sled of firewood. Ninety years old. Wouldn’t let me help.',j:'Stubborn.',m:'Like every keeper.',h:'avalanche'},
{n:'Ilse',r:'radio volunteer',t:'The weather vane',s:'Ilse got lost in the dark between buildings and is waiting by the iron weather vane, the club’s meeting landmark.',k:'heard the keeper speak about Mom',l:'I’ve been on this net for fifty years. Tonight I finally got to sign off safe.',x:'She once said on air: “My best student is gone. Her kids will come back to the shelter. I’ll wait.”',j:'Her best student was Mom.',m:'And we’re her kids.',h:'night'},
{n:'Otto',r:'club president',t:'Net closed',s:'Otto, the Telegraph Club’s president, stayed on the net until every member checked in. He’s the last one at the Signal Cabin.',k:'kept the cabin’s signed logbook',l:'Net closed. All stations accounted for. Seventy-three!',j:'Last one at the Signal Cabin.',m:'And the logbook.',h:'verify'}]},
{title:'The Choir',arc:'The Pine Bend school choir was rehearsing for the winter concert when the storm hit. The children took shelter in the old church and cabins around it.',levels:[
{n:'Mila',r:'student',t:'The solo',s:'Mila, 10, was about to sing her first solo when the church furnace smoked. She led the youngest kids out into the clean air.',k:'knows a song the radio voice hums',l:'I didn’t get my solo. I got everyone outside. That’s better.',x:'The voice on the radio hums the same song our choir teacher taught us. She said it’s very old.',j:'The shelter lullaby.',m:'Mom sang it to us.',h:'smoke'},
{n:'Aleksi',r:'student',t:'Bass section',s:'Aleksi, 14, the only bass in the choir, is waiting with two altos behind a fallen power line on the church lane.',k:'recorded the voice humming',l:'Everyone laughs at my low notes. Nobody laughed tonight.',x:'I recorded the radio humming and our teacher cried. She said only one person knew all the verses.',j:'Katya.',m:'She taught the lullaby to Mom.',h:'cable'},
{n:'Signe',r:'choir teacher',t:'The cold room',s:'Signe, the choir teacher, kept twelve children warm in a cabin with one stove until the wood ran low.',k:'knows who taught the shelter lullaby',l:'Twelve children, twelve songs, one stove. We made it.',x:'The lullaby was written by the first shelter keeper for the children stranded in the big storm of ’61.',j:'1961. She’s been doing this since 1961.',m:'Since before Mom was born.',h:'cold'},
{n:'Nils',r:'student',t:'The concert message',s:'Nils, 12, got a message saying the concert had moved to the hotel site on the ridge. He asked his teacher before going anywhere.',k:'knows why the hotel site was mentioned',l:'The concert’s at Pine Bend. It’s always at Pine Bend.',x:'The hotel developers wanted families on the ridge to make the shelter look abandoned.',j:'They want everyone to forget the shelter.',m:'Then we sing louder.',h:'radio'},
{n:'Tove',r:'pianist',t:'The church safe',s:'Tove, the choir pianist, refused to give the church safe code to “building inspectors” who arrived mid-storm.',k:'found an old program in the safe',l:'The safe holds the choir’s history. History isn’t for strangers.',x:'In the safe: a 1961 concert program. Soloist: “Katya, age 25, keeper of the shelter.”',j:'Katya sang here.',m:'And then she kept the shelter for sixty years.',h:'code'},
{n:'Kari',r:'school nurse',t:'The asthma box',s:'Kari, the school nurse, sealed the choir’s inhalers and allergy pens in one box. It must reach the shelter.',k:'met the beacon keeper years ago',l:'Fifty kids, fifty sets of lungs. They all sang tonight.',x:'Katya trained me in first aid forty years ago. She said, “The shelter is wherever someone keeps the room warm.”',j:'Keep the room warm.',m:'That’s our job now.',h:'medicine',sup:1},
{n:'Emil',r:'student',t:'The skating pond',s:'Emil, 9, wanted to slide on the frozen church pond. He stopped at the warning fence and waited for his teacher instead.',k:'saw a lantern on the mountain',l:'I really wanted to slide. But the sign said thin ice, so I didn’t.',x:'From the pond I saw a lantern blink on the mountain, three times, every hour.',j:'Three blinks. Like a heartbeat.',m:'Like a lighthouse.',h:'ice'},
{n:'Liv',r:'parent',t:'The pass road',s:'Liv, a parent, could have driven the iced pass road to collect her kids early. She parked at the closure and waited for the plows.',k:'heard the voice talk to her son',l:'Every part of me wanted to drive up that road. The smart part won.',x:'The radio voice told my son: “Your mother is safe at the closure. Sing for her.” He did.',j:'She talks to the kids.',m:'Like a grandmother.',h:'crossing'},
{n:'Ebba',r:'student',t:'The bell tower',s:'Ebba, 11, got separated in the snow and remembered to wait under the church bell tower, the choir’s meeting point.',k:'learned the lullaby’s last verse',l:'I waited under the bell and sang so I wouldn’t be scared.',x:'The last verse goes: “The light is on, the door is wide, there’s always room for one inside.”',j:'There’s always room for one inside.',m:'Mom wrote that on the shelter wall.',h:'landmark'},
{n:'Agnetha',r:'choir director',t:'Final bow',s:'Agnetha has led the Pine Bend choir for thirty years. She won’t leave until every child is with their family.',k:'knows who taught her the lullaby',l:'Thirty years of concerts. Tonight, everyone came home. That’s my best show.',j:'Last one at Pine Bend.',m:'And the song.',h:'verify'}]},
{title:'The Plow Crew',arc:'The Snow Depot’s plow crew has fought the storm for two days straight. Now the plows are stuck and the crew is scattered.',levels:[
{n:'Jarno',r:'plow driver',t:'Thirty hours',s:'Jarno has been plowing for thirty hours. His cab heater died on the pass and he’s waiting in the depot shed.',k:'plowed a path to the beacon every week',l:'Thirty hours keeping roads open. I forgot someone might keep one open for me.',x:'Every Sunday someone asks us to plow the beacon track. The work order is signed “K.”',j:'K again.',m:'She’s been asking for help all along.',h:'cold'},
{n:'Raisa',r:'mechanic',t:'The depot line',s:'Raisa, the depot mechanic, is stuck behind an iced power line that fell across the yard.',k:'repaired the beacon’s generator',l:'I fix plows. I can’t fix the weather.',x:'I rebuilt an old generator for the beacon last month. She paid me in firewood and soup.',j:'Soup?',m:'Mom’s soup recipe. It was Katya’s first.',h:'cable'},
{n:'Esko',r:'salt truck driver',t:'Meltwater',s:'Esko’s salt truck slid into a meltwater dip. He climbed to the dry bank and is waiting with his radio.',k:'heard the voice warn the plows',l:'I salt roads so people stay on them. I stayed on mine.',x:'The voice said: “Plow four, the dip at mile six is under water. Stop.” I stopped. Barely.',j:'She sees everything from up there.',m:'Because she’s been watching for sixty years.',h:'water'},
{n:'Kirsi',r:'dispatcher',t:'The fake route',s:'Kirsi got an order to send all plows to the hotel site and leave the shelter road unplowed. She held the trucks and asked Jun to check.',k:'traced who ordered the fake route',l:'Plows go where people are. The order didn’t make sense.',x:'The order came from the developer. They wanted the shelter road snowed in for good.',j:'They tried to bury the shelter.',m:'They tried to bury Katya.',h:'radio'},
{n:'Hannu',r:'depot chief',t:'The fuel card',s:'Hannu refused to read the depot’s fuel card number to a caller claiming to be the county. He locked the pumps.',k:'knows who keeps the shelter’s fuel full',l:'That fuel keeps the pass open. Nobody steals the pass.',x:'Someone fills the shelter’s fuel tank every month. Always in cash. Always with a peppermint left on the cap.',j:'Peppermints.',m:'Katya.',h:'code'},
{n:'Riikka',r:'medic',t:'The cold kit',s:'Riikka, the depot’s medic, sealed the hypothermia kit for the stranded drivers. It must reach the shelter.',k:'treated a plow driver the keeper rescued',l:'Every driver who comes in shivering goes home warm. That’s my rule.',x:'Last winter the keeper dragged a frozen plow driver into the beacon and kept him warm all night.',j:'At ninety?',m:'At eighty-nine.',h:'medicine',sup:1},
{n:'Väinö',r:'student',t:'The ice reservoir',s:'Väinö, 13, saw his dog go out on the frozen depot reservoir and stayed behind the fence, calling until she came back.',k:'met the keeper with his dog',l:'She came back. I knew she would. I just had to be patient.',x:'The keeper met my dog once and said, “I had a dog like you. Her name was Mara.”',j:'She named a dog after you?',m:'After Mom’s favorite name for me.',h:'gate'},
{n:'Aune',r:'plow driver',t:'Snow on the bridge',s:'Aune could have pushed her plow across the snow-loaded bridge. She stopped and waited for the engineer.',k:'saw the keeper on the bridge road',l:'A plow on a weak bridge is just a very heavy mistake.',x:'The keeper walks the bridge road every night with a lantern, checking for stranded cars.',j:'Every night.',m:'Alone.',h:'avalanche'},
{n:'Eero',r:'mechanic',t:'The yellow pole',s:'Eero got lost walking between sheds and waited by the yellow snow pole, the depot’s meeting landmark.',k:'heard what the keeper is waiting for',l:'Twenty years at this depot. Never got lost before tonight.',x:'She told me she’s waiting for the shelter to be warm again before she comes down. Then she can rest.',j:'The shelter is warm now. We fixed it.',m:'Then we tell her.',h:'landmark'},
{n:'Pirkko',r:'crew chief',t:'Plows parked',s:'Pirkko, the plow crew chief, refused to leave until every plow was parked and every driver accounted for.',k:'knows what was left at the Snow Depot',l:'Two days, forty plows, zero lost. Now I sleep.',j:'Last one at the Snow Depot.',m:'And the firewood.',h:'verify'}]},
{title:'The Wedding Party',arc:'Emma and Joel were getting married at the Ice Bridge chapel. The storm split the wedding party across the valley.',levels:[
{n:'Joel',r:'groom',t:'The groom',s:'Joel, the groom, walked his elderly grandparents out of the smoky chapel when its stove backdrafted.',k:'got an unexpected wedding gift',l:'I was supposed to say “I do” today. I said “follow me” instead.',x:'On the gift table: a hand-knitted blanket with a card: “For the new couple. Keep the room warm. — K.”',j:'She knits too.',m:'She taught Mom to knit.',h:'smoke'},
{n:'Emma',r:'bride',t:'The bride',s:'Emma, the bride, is waiting in her wedding dress and snow boots behind a fallen power line on the chapel road.',k:'heard the radio voice wish them well',l:'Best wedding story ever. I just want the wedding now.',x:'The radio voice said: “Congratulations to Emma and Joel. Marriage is a warm room. Keep it warm.”',j:'She was listening to the wedding.',m:'She listens to everything.',h:'cable'},
{n:'Torsten',r:'best man',t:'The rings',s:'Torsten, the best man, has the rings in his pocket and is waiting on the dry side of the flooded valley road.',k:'saw the keeper at the chapel',l:'I had one job. The rings. I’ve still got them.',x:'An old woman in a red coat lit candles in the chapel before the storm, then walked up the mountain.',j:'She lit the chapel.',m:'She lights everything.',h:'water'},
{n:'Maja',r:'bridesmaid',t:'The fake venue',s:'Maja got a message that the wedding had moved to the new hotel on the ridge. She called the bride’s mother instead of going.',k:'knows why the hotel invited the wedding',l:'Emma would never move her wedding to a hotel. Never.',x:'The developer wanted wedding photos at the hotel to advertise it as “the pass’s new shelter.”',j:'They want to replace the shelter.',m:'They can’t replace Katya.',h:'radio'},
{n:'Gustav',r:'photographer',t:'The photo card',s:'Gustav, the wedding photographer, refused to unlock his camera for “hotel marketing” people. He hid the card in his sock.',k:'photographed the beacon at dusk',l:'Those photos belong to the couple. Nobody else.',x:'My dusk photo: the beacon lit, and a small figure at the top waving toward the shelter.',j:'She’s waving at the shelter.',m:'At us.',h:'code'},
{n:'Hilde',r:'caterer',t:'The cake and the insulin',s:'Hilde, the caterer, sealed the wedding cake and a guest’s insulin in the cold box. Both need to reach the shelter.',k:'cooked a meal for the keeper',l:'A wedding without cake is a meeting. This wedding will have cake.',x:'I bring the keeper soup every Friday. She asks about “the kids” every time.',j:'The kids.',m:'Us.',h:'medicine',sup:1},
{n:'Pelle',r:'ring bearer',t:'The ring pillow',s:'Pelle, 6, the ring bearer, stayed behind the fence at the chapel’s frozen fountain when his pillow blew onto the ice.',k:'got a peppermint from the red-coat lady',l:'The pillow can wait. That’s what the red lady said.',x:'The red lady gave me a peppermint and said she’d had a wedding at this chapel too, long ago.',j:'Katya was married here?',m:'And widowed young. Then she gave her life to the shelter.',h:'ice'},
{n:'Ingeborg',r:'grandmother',t:'The ice bridge',s:'Ingeborg, Joel’s grandmother, could have let her grandson carry her over the ice bridge. She told him to wait for the tow truck.',k:'knew the keeper when they were young',l:'Ninety years of winters. I know an ice bridge you don’t cross.',x:'Katya and I were girls together. She always said the ice bridge would crack one day. She called it.',j:'She’s been right about everything.',m:'Sixty years of being right.',h:'crossing'},
{n:'Sten',r:'violinist',t:'The chapel lamp',s:'Sten, the wedding violinist, got lost in the dark and waited by the chapel’s iron lamp, the meeting spot the couple chose.',k:'played the keeper’s lullaby',l:'I played that lullaby for the bride’s entrance. Felt like the mountain was listening.',x:'When I played the lullaby, the beacon blinked three times. Like applause.',j:'She heard.',m:'She hears everything.',h:'night'},
{n:'Margareta',r:'wedding officiant',t:'I do',s:'Margareta, the officiant, refused to leave the chapel until the whole wedding party was safe, so she could finish the vows later.',k:'knows what happened at the Ice Bridge',l:'I’ve married a hundred couples. Tonight I made sure all their guests got home.',j:'Last one at the Ice Bridge.',m:'And the warning.',h:'verify'}]},
{title:'The Weather Station',arc:'Ridge Station’s weather scientists measure every storm on the pass. Tonight the storm measured them.',levels:[
{n:'Petra',r:'meteorologist',t:'Data smoke',s:'Petra, the lead meteorologist, evacuated the station when a server overheated and smoked. She’s waiting outside with the backup drives.',k:'compared the beacon’s forecasts with her own',l:'I predict storms for a living. Didn’t predict this one.',x:'The beacon’s nine o’clock forecast beats our computers every night. She reads the clouds by eye.',j:'Better than computers.',m:'Sixty years of looking up.',h:'smoke'},
{n:'Lauri',r:'technician',t:'The mast cable',s:'Lauri, a technician, is stuck below the anemometer mast after its iced cable fell across the path.',k:'found the keeper’s old instruments',l:'I fix instruments that measure wind. Tonight I just needed it to stop.',x:'In the station attic: old barometers labeled “Shelter — K.” She ran this station before we did.',j:'She built this place too.',m:'She built half the pass.',h:'cable'},
{n:'Zofia',r:'glaciologist',t:'Meltwater lab',s:'Zofia, a glaciologist, retreated to the station roof when meltwater flooded the lab door.',k:'measured the beacon’s light',l:'I study ice. Tonight the ice studied me.',x:'The beacon’s lamp is the old shelter lamp. Same wavelength. Same bulb type. It was moved up there eight years ago.',j:'Eight years ago. When the shelter closed.',m:'She took the light with her.',h:'water'},
{n:'Mattias',r:'student researcher',t:'The false alert',s:'Mattias, a student, saw an alert telling staff to evacuate toward the hotel site. He checked with Petra and stayed put.',k:'knows who faked the alert',l:'The alert said hotel. Petra said no. Petra’s my boss.',x:'The developer faked the alert to empty Ridge Station before the storm data proved the shelter was needed.',j:'The data proves the shelter is needed.',m:'Then the data goes public.',h:'radio'},
{n:'Anneli',r:'data manager',t:'The archive',s:'Anneli refused to give the climate archive password to a “partner” asking for storm data. She locked the server room.',k:'found the keeper’s storm records',l:'Sixty years of weather in that archive. Not for sale.',x:'The oldest records are handwritten: sixty years of storms, each one ending “All home. — K.”',j:'All home.',m:'Every storm.',h:'code'},
{n:'Jussi',r:'medic',t:'The altitude kit',s:'Jussi, the station medic, sealed the altitude-sickness kit for evacuees. It must reach the shelter.',k:'checked the keeper’s breathing last month',l:'Thin air, cold air. My job is making sure everyone keeps breathing.',x:'Her lungs are strong, but her heart is tired. She said she just needs to see the shelter warm once more.',j:'Once more.',m:'Then we make sure she sees it.',h:'medicine',sup:1},
{n:'Rasmus',r:'student',t:'The rain gauge pond',s:'Rasmus, 12, on a school visit, saw the rain-gauge pond overflowing and stayed behind its fence until a scientist came.',k:'saw a message the keeper left',l:'I wanted to measure the water. From a safe distance.',x:'Scratched on the pond fence: “Measure twice. Cross never. — K.”',j:'Her rules are everywhere.',m:'She left them for us.',h:'gate'},
{n:'Tuva',r:'snow surveyor',t:'Cornice',s:'Tuva saw the cornice above the station road crack and turned back to wait in the vehicle bay.',k:'saw the keeper’s path',l:'Snow is beautiful from a distance. That’s the distance I chose.',x:'Her path to the beacon zigzags to avoid every cornice. She’s walked it for sixty years.',j:'Sixty years, one path.',m:'Tonight we walk it with her.',h:'avalanche'},
{n:'Erik',r:'astronomer',t:'The dome',s:'Erik got stranded at night when his snowcat stalled. He’s waiting by the observatory dome’s red light.',k:'saw the keeper at the beacon tonight',l:'I look at stars. Tonight I just wanted headlights.',x:'Through my telescope: she’s at the beacon window, wrapped in blankets, with the radio on.',j:'She’s right there.',m:'Then let’s go.',h:'night'},
{n:'Kristina',r:'station director',t:'Shutdown',s:'Kristina, the station director, stayed to shut down the instruments safely and account for every researcher.',k:'knows the keeper’s secret channel',l:'Every instrument off, every scientist out. Now the director leaves.',j:'Last one at Ridge Station.',m:'And the channel.',h:'verify'}]},
{title:'The Hockey Team',arc:'The Tunnel Mouth junior hockey team’s bus stalled at the tunnel entrance. The kids and coaches took shelter in the old maintenance rooms.',levels:[
{n:'Coach Jonas',r:'hockey coach',t:'The bus fire',s:'Coach Jonas got sixteen kids off the team bus when its engine smoked at the tunnel mouth.',k:'saw someone climbing the mountain',l:'Sixteen kids, sixteen helmets, sixteen heads counted. Then I breathed.',x:'Above the tunnel, a figure with a lantern was climbing slowly toward the summit.',j:'Climbing. At night.',m:'In this storm.',h:'smoke'},
{n:'Selma',r:'student',t:'Goalie',s:'Selma, 14, the team’s goalie, is guarding two younger players behind a fallen tunnel light cable.',k:'found bootprints in the tunnel',l:'I block pucks for a living. Tonight I blocked the cable.',x:'In the tunnel, small bootprints, slow and steady, going uphill. One person. Alone.',j:'Bootprints toward the summit.',m:'She’s going to the beacon.',h:'cable'},
{n:'Vidar',r:'student',t:'The captain',s:'Vidar, 15, the team captain, got everyone onto the dry maintenance platform when meltwater flooded the tunnel floor.',k:'got a message from the keeper',l:'Captain means you go last. So I went last.',x:'On the tunnel wall, in chalk: “Stay dry. Help comes. — K.”',j:'She leaves notes for everyone.',m:'Like Mom did.',h:'water'},
{n:'Saga',r:'team manager',t:'The fake bus',s:'Saga got a text saying a replacement bus was waiting at the hotel road. She called the bus company first and stayed.',k:'knows why the hotel sent a fake bus',l:'Sixteen kids. I don’t move them on a text.',x:'The developer wanted the team photographed at the hotel as “rescued by the new resort.”',j:'They want credit for rescues they didn’t do.',m:'The shelter did them.',h:'radio'},
{n:'Anton',r:'student',t:'The team tablet',s:'Anton, 13, refused to unlock the team tablet for a man claiming to be the league. It has every kid’s emergency contacts.',k:'saw the keeper’s message on the tablet',l:'Coach said the tablet’s like the net. Nothing gets past.',x:'An unknown sender messaged the team: “Stay in the tunnel. Warm room at the shelter tomorrow.” Signed K.',j:'She knew they were there.',m:'She knows where everyone is.',h:'code'},
{n:'Lena',r:'team medic',t:'The sports kit',s:'Lena, the team medic, sealed the injury and asthma kit for the kids. It needs to reach the shelter.',k:'met the keeper years ago',l:'Bruises, sprains, and one homesick goalie. All treated.',x:'The keeper ran first-aid camps for kids when I was little. She said: “The shelter is a promise.”',j:'A promise.',m:'That someone will always come.',h:'medicine',sup:1},
{n:'Oliver',r:'student',t:'The frozen rink',s:'Oliver, 10, the youngest player, wanted to skate on the frozen reservoir by the tunnel. He stopped at the fence when he saw the sign.',k:'saw the beacon from the reservoir',l:'I wanted to practice. I can practice at home.',x:'From the reservoir, the beacon light pointed straight at the shelter. Like it was saying “there.”',j:'It points at the shelter.',m:'It always did.',h:'ice'},
{n:'Mira',r:'bus driver',t:'The tunnel road',s:'Mira, the bus driver, could have tried the snowed-in tunnel road. She waited for the plow crew instead.',k:'heard the keeper on the bus radio',l:'I drive kids. I don’t gamble with them.',x:'The bus radio crackled: “Driver, wait for the plow. The road will be open by dawn. — Beacon.”',j:'She talked to the driver.',m:'She talks to everyone who’s scared.',h:'crossing'},
{n:'Hugo',r:'student',t:'The hockey stick sign',s:'Hugo, 12, wandered off to find signal and waited at the giant hockey-stick sign, the team’s meeting landmark.',k:'heard the keeper’s last message',l:'I found signal. I also found I should have stayed with the team.',x:'Her last message tonight: “I’m going up to the beacon one more time. Tell the kids I’ll wait.”',j:'One more time.',m:'Then we go up to get her.',h:'landmark'},
{n:'Coach Britta',r:'head coach',t:'Final whistle',s:'Coach Britta refused to leave the Tunnel Mouth until every player had been picked up by family.',k:'knows what the bootprints mean',l:'Final whistle. Everyone’s home. Best game we ever played.',j:'Last one at the Tunnel Mouth.',m:'And the bootprints.',h:'verify'}]},
{title:'Mountain Mail',arc:'The Summit Road mail route reaches the highest homes on the pass. Tonight its letter carrier and the people she serves are snowed in.',levels:[
{n:'Elsa',r:'letter carrier',t:'Last route',s:'Elsa, the letter carrier, got caught when a chimney fire smoked across Summit Road. She’s waiting upwind with her mail sack.',k:'delivers mail to the beacon',l:'Neither snow nor smoke. But tonight, both.',x:'I deliver one letter a week to the beacon. Always from the shelter’s old address. Always returned unopened.',j:'Letters from the shelter.',m:'Mom wrote to her.',h:'smoke'},
{n:'Johan',r:'retired miner',t:'The mine line',s:'Johan, a retired miner, is stuck behind a power line that fell across his driveway.',k:'shared firewood with the keeper',l:'I spent forty years underground. I like the sky better.',x:'Every winter the keeper and I trade firewood for candles. She says she’s saving the candles for a homecoming.',j:'A homecoming.',m:'Ours.',h:'cable'},
{n:'Lumi',r:'student',t:'The snowman',s:'Lumi, 8, was building a snowman when meltwater flooded the road below her house. She waited on the porch steps.',k:'got a letter from the keeper',l:'My snowman is still standing. So am I.',x:'The keeper sent me a letter: “Snowmen and keepers are alike. We stand still and wait for spring.”',j:'Waiting for spring.',m:'Waiting for us.',h:'water'},
{n:'Martti',r:'postmaster',t:'The fake redirect',s:'Martti got an order to redirect all Summit mail to the hotel’s new post box. He refused without a signed form.',k:'knows what the hotel wanted from the mail',l:'Mail goes where it’s addressed. That’s the whole job.',x:'They wanted the keeper’s letters. Her letters prove she still runs the shelter.',j:'Proof she’s the keeper.',m:'Then she keeps the shelter.',h:'radio'},
{n:'Greta',r:'post clerk',t:'The parcel lockers',s:'Greta refused to read the parcel locker codes to a caller pretending to be a delivery company.',k:'found a parcel addressed to Mara and Jun',l:'Parcels are promises. I keep promises.',x:'In locker nine: a parcel addressed to “Mara and Jun, the shelter.” Postmarked eight years ago. Never collected.',j:'Eight years waiting for us.',m:'We’ll open it together.',h:'code'},
{n:'Aslak',r:'pharmacist',t:'Mountain prescriptions',s:'Aslak, the summit pharmacist, sealed every resident’s prescriptions in one box for the shelter.',k:'fills the keeper’s prescriptions',l:'Fifty houses on this road. Fifty bottles of medicine. All accounted for.',x:'Her prescriptions say “do not climb stairs.” She lives at the top of a tower.',j:'Stubborn.',m:'Like Mom. Like you.',h:'medicine',sup:1},
{n:'Klara',r:'student',t:'The pond rope',s:'Klara, 11, stopped at the rope fence when her cat ran out on the summit pond and coaxed it back with treats.',k:'saw the keeper’s lantern tonight',l:'The cat came back. Cats always come back. Eventually.',x:'Tonight the lantern at the beacon is moving. Down the tower stairs. Slowly.',j:'She’s coming down.',m:'She’s coming down to meet us.',h:'ice'},
{n:'Bjørn',r:'snowcat driver',t:'The summit pass',s:'Bjørn could have driven his snowcat over the cracked summit pass. He waited for the avalanche crew’s all-clear.',k:'drove the keeper up the mountain years ago',l:'A snowcat weighs eight tons. The mountain weighs more.',x:'Eight years ago I drove her up to the beacon. She said: “When the shelter is warm again, they’ll come for me.”',j:'The shelter is warm again.',m:'We’re coming.',h:'avalanche'},
{n:'Dagny',r:'innkeeper',t:'The lantern sign',s:'Dagny, the summit innkeeper, got lost in the whiteout and waited under her inn’s lantern sign.',k:'knows where the keeper is right now',l:'I give travelers shelter. Tonight I needed one.',x:'She’s halfway down the beacon stairs with her lantern. She’s waiting for you at the bottom.',j:'Waiting at the bottom of the beacon.',m:'For us.',h:'night'},
{n:'Ragnhild',r:'mail route chief',t:'Last delivery',s:'Ragnhild runs the Summit mail route. She won’t leave until every house on the road is checked.',k:'knows what the snowplow driver saw',l:'Every letter delivered, every door knocked. Now I go home.',j:'Last one on Summit Road.',m:'And the lantern.',h:'verify'}]},
{title:'The Keepers',arc:'The White Beacon is where the shelter’s keepers once watched the pass. Tonight the last of them are waiting there for the light to come home.',levels:[
{n:'Old Anders',r:'former keeper',t:'Smoke at the beacon',s:'Old Anders kept the shelter in the 1980s. Smoke from the beacon’s stove drove him out into the snow.',k:'kept the shelter with Katya',l:'I kept the shelter eight years. Katya kept it sixty.',x:'Katya never left the beacon after the shelter closed. She said someone had to watch the pass.',j:'She watched the pass for eight years alone.',m:'Not alone anymore.',h:'smoke'},
{n:'Maren',r:'former keeper',t:'The keeper’s line',s:'Maren, a former keeper, is stuck below the beacon behind the old telephone line, sagging with ice.',k:'remembers Mom at the shelter',l:'Your mother was the best keeper I ever trained beside.',x:'Your mother kept the shelter for Katya when Katya got old. She was her heir.',j:'Mom was going to be the next keeper.',m:'And now it’s us.',h:'cable'},
{n:'Henning',r:'former keeper',t:'The melt',s:'Henning, a former keeper, waited on the beacon rocks when meltwater rose around the path.',k:'knows why the shelter closed',l:'I kept the shelter in the nineties. I never thought I’d need it.',x:'The shelter closed when your mother died. Katya couldn’t keep it alone. So she kept the light instead.',j:'She kept the light for Mom.',m:'And for us.',h:'water'},
{n:'Agda',r:'former keeper',t:'The false keeper',s:'Agda got a message from someone claiming to be the new shelter keeper, ordering her down to the hotel. She refused and stayed at the beacon.',k:'knows who the real keepers are',l:'There’s no keeper at the hotel. The keepers are here.',x:'The developer hired an actor to call himself the keeper. Katya laughed for an hour.',j:'Katya laughs?',m:'Mom said she had the best laugh.',h:'radio'},
{n:'Torvald',r:'former keeper',t:'The deed',s:'Torvald, a former keeper, refused to give the shelter deed box code to “lawyers” who came up the mountain.',k:'knows what the deed says',l:'That box has kept the shelter safe for sixty years.',x:'The deed says the shelter belongs to “whoever keeps the room warm.” That’s you now.',j:'The shelter is ours.',m:'Because we kept it warm.',h:'code'},
{n:'Signhild',r:'medic',t:'The keeper’s medicine',s:'Signhild, the beacon’s visiting nurse, sealed Katya’s medicines for the trip down. They need to reach the shelter.',k:'cares for Katya every week',l:'Ninety years old. She deserves a warm room.',x:'Katya’s heart is tired. She told me: “When the kids light the shelter, I’ll come down. Not before.”',j:'The shelter is lit.',m:'Then it’s time.',h:'medicine',sup:1},
{n:'Ivo',r:'student',t:'The beacon pond',s:'Ivo, 7, Signhild’s grandson, stayed behind the fence at the frozen beacon pond, waving his flashlight to guide his grandmother.',k:'brought Katya peppermints today',l:'I brought her peppermints. She gave me one back. That’s the rule.',x:'Katya said: “Tell Mara and Jun there’s a peppermint waiting.”',j:'A peppermint.',m:'Like when we were little.',h:'ice'},
{n:'Halvard',r:'former keeper',t:'The beacon bridge',s:'Halvard could have crossed the snow-loaded beacon footbridge. He waited for the all-clear instead.',k:'helped Katya down the stairs tonight',l:'Eighty years old and still learning patience.',x:'I helped Katya down the stairs. She’s at the beacon door, wrapped in her red coat, waiting.',j:'She’s waiting for us.',m:'We’re almost there.',h:'avalanche'},
{n:'Elisabet',r:'former keeper',t:'The keepers’ cairn',s:'Elisabet, a former keeper, got turned around in the whiteout and waited by the keepers’ stone cairn.',k:'knows what Katya will say',l:'Every keeper added a stone to this cairn. Tonight I sat on it.',x:'Katya told me what she’ll say when she sees you: “The room is warm. I can rest now.”',j:'She can rest.',m:'We’ll keep it warm. Forever.',h:'landmark'},
{n:'Katya',r:'shelter keeper',t:'The keeper',s:'Katya, 90, the shelter’s first keeper, has watched the pass from the White Beacon for eight years. Tonight she’s waiting at the door to come home.',k:'kept the light on',l:'The room is warm. I can rest now. Thank you, both of you.',j:'Katya.',m:'Let’s take you home.',h:'verify'}]}
]};
